  const line = {
    sku: 'CUSTOM',
    name: 'Custom item',
    qty: 3,
    unitPrice: 100.33,
    vatRate: 21,
  };

  // 3 × 100.33 = 300.99
  assert.equal(lineTotal(line), 301);
