test('lineTotal rounds half to even', () => {
  const line1 = {
    sku: 'CUSTOM',
    name: 'Custom item',
    qty: 2,
    unitPrice: 1.25,
    vatRate: 21,
  };

  const line2 = {
    sku: 'CUSTOM',
    name: 'Custom item',
    qty: 2,
    unitPrice: 1.75,
    vatRate: 21,
  };

  // 2 × 1.25 = 2.5, rounds to 2 (even)
