test('invoiceTotals with VAT calculation', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);
  // subtotal = 10 × 9500 = 95000
  // discount = 0 (standard tier)
  // VAT = 95000 × 21 / 100 = 19950
  // total = 95000 - 0 + 19950 = 114950
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 19950);
  assert.equal(totals.total, 114950);
});

test('invoiceTotals with multiple lines and VAT', () => {
