      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  const totals = invoiceTotals(result.value);
  // DEV-HOUR: 10 × 9500 = 95000, VAT = 95000 × 21 / 100 = 19950
  // DES-HOUR: 5 × 8500 = 42500, VAT = 42500 × 21 / 100 = 8925
  // subtotal = 137500, discount = 0, VAT = 28875
  // total = 137500 - 0 + 28875 = 166375
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 28875);
  assert.equal(totals.total, 166375);
});

test('invoiceTotals with discount and VAT', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  });

  const totals = invoiceTotals(result.value);
  // subtotal = 95000
  // discount = 95000 × 10 / 100 = 9500
  // taxable = 95000 - 9500 = 85500
  // VAT = 85500 × 21 / 100 = 17955
  // total = 95000 - 9500 + 17955 = 103455
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 9500);
  assert.equal(totals.vat, 17955);
  assert.equal(totals.total, 103455);
});

test('invoiceTotals with tier discount and VAT', () => {
  // C-001 is gold tier (5% discount)
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  const totals = invoiceTotals(result.value);
  // subtotal = 95000
  // discount = 95000 × 5 / 100 = 4750
  // taxable = 95000 - 4750 = 90250
  // VAT = 90250 × 21 / 100 = 18952.5 → 18952 (banker's rounding, rounds to even)
  // total = 95000 - 4750 + 18952 = 109202
  assert.equal(totals.subtotal, 95000);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 18952);
  assert.equal(totals.total, 109202);
});

test('invoiceTotals with mixed VAT rates', () => {
  const result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'PRINT-A4', qty: 100 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  });

  const totals = invoiceTotals(result.value);
  // DEV-HOUR (21%): 95000, VAT = 19950
  // PRINT-A4 (9%): 100 × 37 = 3700, VAT = 3700 × 9 / 100 = 333
  // WORKSHOP-DAY (0%): 60000, VAT = 0
  // subtotal = 158700, discount = 0, VAT = 20283
  // total = 158700 - 0 + 20283 = 178983
  assert.equal(totals.subtotal, 158700);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, 20283);
  assert.equal(totals.total, 178983);
});

